// The update log (updates.ts) in every language: updates 63 to 66. See updates.ts in this folder.
import type { Row } from "./table.ts";

export const UPDATES13: Readonly<Record<string, Row>> = {
  "Eternal night in the Deadwood, the Realm's music made full and dark, and coffers once an hour": ["Deadwood の永遠の夜、厚く暗くなったレルムの音楽、そして1時間ごとの宝箱", "Deadwood의 영원한 밤, 풍성하고 어두워진 렐름의 음악, 그리고 한 시간마다의 보물상자", "Deadwood 的永夜、更饱满深沉的王国音乐，以及每小时一次的宝箱", "Deadwood 的永夜、更飽滿深沉的王國音樂，以及每小時一次的寶箱", "Đêm vĩnh hằng ở Deadwood, nhạc Vương quốc đầy đặn và u tối, và rương báu mỗi giờ một lần", "Malam abadi di Deadwood, musik Realm yang penuh dan gelap, dan peti sekali sejam", "ราตรีนิรันดร์ใน Deadwood ดนตรีของอาณาจักรที่เต็มและมืดขึ้น และหีบสมบัติชั่วโมงละครั้ง", "Deadwood'da sonsuz gece, Diyar'ın dolgun ve koyu müziği ve saatte bir sandıklar", "Noche eterna en el Deadwood, la música del Reino más llena y oscura, y cofres una vez por hora", "Noite eterna no Deadwood, a música do Reino cheia e sombria, e baús uma vez por hora", "Вечная ночь в Deadwood, полная и мрачная музыка Королевства и сундуки раз в час", "Вічна ніч у Deadwood, повна й похмура музика Королівства та скрині раз на годину"],
  "An ancient magic keeps a cloud over the whole Deadwood now, and no sun gets through: it is always night under the dead trees, the lamps and crypt-fires the only light, and the wood's own ground is darker than anywhere in the Realm. The dark comes on as you walk in from Gravesend and lifts as you leave.": ["古の魔法が Deadwood 全体を雲で覆い、日の光は届きません：枯れ木の下はいつも夜で、明かりはランプと墓所の火だけ、森の地面はレルムのどこよりも暗い。グレイヴセンドから入ると闇が下り、出ると晴れます。", "고대의 마법이 이제 Deadwood 전체에 구름을 드리워 햇빛이 들지 않습니다: 죽은 나무 아래는 늘 밤이고, 빛은 등불과 묘지의 불뿐이며, 숲의 땅은 렐름 어디보다 어둡습니다. 그레이브센드에서 걸어 들어가면 어둠이 내리고, 나가면 걷힙니다.", "一种古老的魔法如今让云层笼罩整个 Deadwood，阳光无法透入：枯树下永远是夜晚，只有灯和墓火照明，林地比王国任何地方都暗。从墓终走进时黑暗降临，离开时散去。", "一種古老的魔法如今讓雲層籠罩整個 Deadwood，陽光無法透入：枯樹下永遠是夜晚，只有燈和墓火照明，林地比王國任何地方都暗。從墓終走進時黑暗降臨，離開時散去。", "Một ma thuật cổ xưa giữ một đám mây trên toàn Deadwood, và không tia nắng nào lọt qua: dưới những cây chết luôn là đêm, đèn và lửa hầm mộ là ánh sáng duy nhất, và mặt đất của khu rừng tối hơn bất cứ đâu trong Vương quốc. Bóng tối phủ xuống khi bạn bước vào từ Gravesend và tan khi bạn rời đi.", "Sihir kuno kini menahan awan di atas seluruh Deadwood, dan tak ada matahari yang tembus: di bawah pohon mati selalu malam, lampu dan api kripta satu-satunya cahaya, dan tanah hutannya lebih gelap dari mana pun di Realm. Gelap datang saat kau masuk dari Gravesend dan terangkat saat kau pergi.", "เวทมนตร์โบราณทำให้มีเมฆปกคลุม Deadwood ทั้งหมด แสงอาทิตย์ส่องไม่ผ่าน: ใต้ต้นไม้ตายเป็นกลางคืนเสมอ ตะเกียงและไฟในสุสานเป็นแสงเดียว และพื้นป่ามืดกว่าที่ใดในอาณาจักร ความมืดคลืบคลานมาเมื่อเดินเข้ามาจากเกรฟเซนด์และจางไปเมื่อคุณออก", "Kadim bir büyü artık tüm Deadwood'un üstünde bir bulut tutuyor ve hiç güneş geçmiyor: kuru ağaçların altında hep gece; tek ışık lambalar ve mahzen ateşleri ve ormanın zemini Diyar'ın her yerinden karanlık. Gravesend'den girerken karanlık çöker, çıkarken kalkar.", "Una magia antigua mantiene ahora una nube sobre todo el Deadwood y no pasa ni un rayo de sol: bajo los árboles muertos siempre es de noche, los faroles y los fuegos de las criptas son la única luz y el suelo del bosque es más oscuro que en ningún otro lugar del Reino. La oscuridad llega al entrar desde Gravesend y se levanta al salir.", "Uma magia antiga mantém agora uma nuvem sobre todo o Deadwood, e nenhum sol passa: sob as árvores mortas é sempre noite, os lampiões e as fogueiras das criptas são a única luz, e o chão da mata é mais escuro que em qualquer lugar do Reino. O escuro chega quando você entra vindo de Gravesend e se desfaz quando você sai.", "Древняя магия держит теперь облако над всем Deadwood, и солнце не пробивается: под мёртвыми деревьями всегда ночь, единственный свет — фонари и огни склепов, а земля леса темнее, чем где-либо в Королевстве. Тьма наступает, когда вы входите со стороны Грейвсенда, и рассеивается, когда уходите.", "Давня магія тримає тепер хмару над усім Deadwood, і сонце не пробивається: під мертвими деревами завжди ніч, єдине світло — ліхтарі й вогні склепів, а земля лісу темніша, ніж будь-де в Королівстві. Темрява настає, коли ви входите з боку Грейвсенда, і розсіюється, коли йдете."],
  "The Realm's music has been reworked to the sound of the Mossy Undercroft: a pad under every chord, a harp picking through it, the tune a little slower and the band a little calmer, so even the cheerful places are full and dark with a bright line over them. The Ring and the boss theme keep their own drums.": ["レルムの音楽を Mossy Undercroft の響きに作り直しました：どの和音の下にもパッドが敷かれ、ハープがその間を爪弾き、旋律は少しゆっくり、演奏は少し穏やかに。明るい場所でさえ、厚く暗い響きの上に明るい旋律が乗ります。リングとボス曲は独自のドラムのままです。", "렐름의 음악을 Mossy Undercroft의 소리로 다시 만들었습니다: 모든 화음 아래 패드가 깔리고, 하프가 그 사이를 뜯으며, 선율은 조금 느리고 연주는 조금 차분해져서, 밝은 곳조차 풍성하고 어두운 소리 위로 밝은 선율이 흐릅니다. 링과 보스 테마는 자기 드럼을 그대로 씁니다.", "王国的音乐已按 Mossy Undercroft 的风格重做：每个和弦下都铺着长音垫，竖琴在其中拨奏，旋律稍慢，乐队稍静，所以即便是欢快的地方，也是饱满深沉的底色上浮着一条明亮的旋律。擂台和首领主题保留各自的鼓。", "王國的音樂已按 Mossy Undercroft 的風格重做：每個和弦下都鋪著長音墊，豎琴在其中撥奏，旋律稍慢，樂隊稍靜，所以即便是歡快的地方，也是飽滿深沉的底色上浮著一條明亮的旋律。擂台和首領主題保留各自的鼓。", "Âm nhạc Vương quốc được làm lại theo âm hưởng của Mossy Undercroft: một lớp nền dưới mỗi hợp âm, đàn hạc gảy xen qua, giai điệu chậm hơn một chút và ban nhạc êm hơn một chút, nên ngay cả những nơi vui tươi cũng đầy đặn và u tối với một nét nhạc sáng phía trên. Đấu trường và nhạc trùm giữ trống riêng.", "Musik Realm digarap ulang dengan suara Mossy Undercroft: pad di bawah setiap akor, harpa memetik di antaranya, melodi sedikit lebih lambat dan band sedikit lebih tenang, jadi bahkan tempat yang ceria pun penuh dan gelap dengan garis terang di atasnya. Ring dan tema bos tetap memakai drum sendiri.", "ดนตรีของอาณาจักรถูกเรียบเรียงใหม่ตามเสียงของ Mossy Undercroft: มีแพดรองทุกคอร์ด ฮาร์ปดีดสอดผ่าน ทำนองช้าลงนิดและวงสงบลงนิด แม้ที่ที่ร่าเริงก็เต็มและมืดพร้อมทำนองสดใสลอยอยู่ข้างบน สังเวียนและธีมบอสยังใช้กลองของตัวเอง", "Diyar'ın müziği Mossy Undercroft'un sesine göre yeniden yapıldı: her akorun altında bir ped, aralarından çalınan bir arp, biraz daha yavaş bir ezgi ve biraz daha sakin bir grup; böylece neşeli yerler bile üstünde parlak bir çizgiyle dolgun ve koyu. Ring ve patron teması kendi davullarını koruyor.", "La música del Reino se ha rehecho al sonido de la Mossy Undercroft: un colchón bajo cada acorde, un arpa punteando entre ellos, la melodía algo más lenta y la banda algo más calmada, de modo que hasta los lugares alegres suenan llenos y oscuros con una línea brillante encima. El Ring y el tema de jefe conservan su propia percusión.", "A música do Reino foi refeita no som da Mossy Undercroft: um pad sob cada acorde, uma harpa dedilhando no meio, a melodia um pouco mais lenta e a banda um pouco mais calma, então até os lugares alegres ficam cheios e sombrios com uma linha clara por cima. O Ringue e o tema de chefe mantêm a própria percussão.", "Музыку Королевства переделали под звучание Mossy Undercroft: под каждым аккордом — пэд, сквозь него перебирает арфа, мелодия чуть медленнее, а ансамбль чуть спокойнее, так что даже весёлые места звучат полно и мрачно с яркой линией сверху. Ринг и тема боссов сохранили свои барабаны.", "Музику Королівства переробили під звучання Mossy Undercroft: під кожним акордом — пед, крізь нього перебирає арфа, мелодія трохи повільніша, а гурт трохи спокійніший, тож навіть веселі місця звучать повно й похмуро з яскравою лінією згори. Ринг і тема босів зберегли свої барабани."],
  "Dungeon coffers and hoards fill again for the one who searched them once an hour now, not every quarter of one: loot, not a living.": ["ダンジョンの宝箱と財宝は、探した人にとって15分ごとではなく1時間ごとに満たされるようになりました：戦利品であって、生計ではありません。", "던전 보물상자와 보물은 이제 뒤진 사람에게 15분이 아니라 한 시간마다 다시 찹니다: 전리품이지, 생계 수단이 아닙니다.", "地下城的宝箱和宝藏现在每小时为搜过的人重新装满一次，而不是每十五分钟：是战利品，不是饭碗。", "地下城的寶箱和寶藏現在每小時為搜過的人重新裝滿一次，而不是每十五分鐘：是戰利品，不是飯碗。", "Rương và kho báu trong hầm ngục giờ đầy lại cho người đã lục mỗi giờ một lần, không phải mỗi mười lăm phút: là chiến lợi phẩm, không phải kế sinh nhai.", "Peti dan timbunan ruang bawah tanah kini terisi lagi bagi yang menggeledahnya sekali sejam, bukan tiap seperempat jam: jarahan, bukan mata pencaharian.", "หีบและกองสมบัติในดันเจี้ยนตอนนี้เติมใหม่ให้คนที่ค้นชั่วโมงละครั้ง ไม่ใช่ทุกสิบห้านาที: เป็นของรางวัล ไม่ใช่อาชีพ", "Zindan sandıkları ve hazineleri artık arayan için çeyrek saatte bir değil, saatte bir yeniden doluyor: ganimet, geçim kaynağı değil.", "Los cofres y tesoros de las mazmorras se vuelven a llenar para quien los registró una vez por hora, no cada cuarto de hora: botín, no un sueldo.", "Os baús e tesouros das masmorras voltam a encher para quem os revistou uma vez por hora agora, não a cada quinze minutos: saque, não um salário.", "Сундуки и клады подземелий теперь снова наполняются для обыскавшего раз в час, а не каждые пятнадцать минут: это добыча, а не заработок.", "Скрині й скарби підземель тепер знову наповнюються для того, хто їх обшукав, раз на годину, а не щоп'ятнадцять хвилин: це здобич, а не заробіток."],
  "Four Orders and their gods, and the Deadwood Maidens": ["4つの騎士団とその神々、そして枯れ森の乙女", "네 기사단과 그들의 신, 그리고 데드우드의 처녀들", "四大骑士团与他们的神，以及枯木少女", "四大騎士團與他們的神，以及枯木少女", "Bốn Dòng và các vị thần của họ, và Thiếu nữ Deadwood", "Empat Ordo dan dewa-dewa mereka, dan Gadis Deadwood", "สี่ภาคีและเทพของพวกเขา และหญิงสาวป่าไม้ตาย", "Dört Tarikat ve tanrıları, ve Deadwood Bakireleri", "Cuatro Órdenes y sus dioses, y las Doncellas de Deadwood", "Quatro Ordens e seus deuses, e as Donzelas de Deadwood", "Четыре Ордена и их боги и Девы Мёртвого леса", "Чотири Ордени та їхні боги й Діви Мертвого лісу"],
  "Four knightly Orders have raised halls in the wider world, each serving a god of legend, a Rare Friend shaped like the sign of a chain. The Order of the Diamond serves the Good Friend (blue as deep water, a diamond on its point) in the Thistle Vale meadows; the Order of the Ink serves the Squid Friend (storm purple) on the Quillhaven headland; the Order of the Sol serves the Weird Friend (a sun of every colour) on the Southshore downs; the Order of the Hood serves the Hood Friend (the green of new leaves) in The Wilds. Statues of the gods stand before each hall and small on each altar.": ["広い世界に4つの騎士団が館を建てました。それぞれが伝説の神、つまりチェーンの印の形をした Rare Friend に仕えています。ダイヤモンド教団はアザミの谷の草原で Good Friend（深い水のような青、先端に立つダイヤ）に、インク教団はクイルヘイヴンの岬で Squid Friend（嵐の紫）に、ソル教団はサウスショアの丘陵で Weird Friend（あらゆる色の太陽）に、フード教団は荒野で Hood Friend（若葉の緑）に仕えます。神々の像が各館の前に、小さな像が各祭壇に立っています。", "넓은 세상에 네 기사단이 회관을 세웠습니다. 각각 전설의 신, 체인의 표식 모양을 한 Rare Friend를 섬깁니다. 다이아몬드 기사단은 엉겅퀴 골짜기 초원에서 Good Friend(깊은 물빛 파랑, 끝으로 선 다이아몬드)를, 잉크 기사단은 퀼헤이븐 곶에서 Squid Friend(폭풍 보라)를, 솔 기사단은 사우스쇼어 구릉에서 Weird Friend(온갖 색의 태양)를, 후드 기사단은 황야에서 Hood Friend(새잎의 초록)를 섬깁니다. 신들의 석상이 각 회관 앞에, 작은 석상이 각 제단에 서 있습니다.", "四个骑士团在更广阔的世界建起了殿堂，各自侍奉一位传说中的神，也就是形似链之标记的 Rare Friend。钻石骑士团在蓟谷草地侍奉 Good Friend（深水般的蓝，一颗竖立的钻石）；墨之骑士团在羽港岬角侍奉 Squid Friend（风暴紫）；日轮骑士团在南岸丘陵侍奉 Weird Friend（五彩的太阳）；兜帽骑士团在荒野侍奉 Hood Friend（新叶的绿）。神像立在各殿堂前，小神像立在各祭坛上。", "四個騎士團在更廣闊的世界建起了殿堂，各自侍奉一位傳說中的神，也就是形似鏈之標記的 Rare Friend。鑽石騎士團在薊谷草地侍奉 Good Friend（深水般的藍，一顆豎立的鑽石）；墨之騎士團在羽港岬角侍奉 Squid Friend（風暴紫）；日輪騎士團在南岸丘陵侍奉 Weird Friend（五彩的太陽）；兜帽騎士團在荒野侍奉 Hood Friend（新葉的綠）。神像立在各殿堂前，小神像立在各祭壇上。", "Bốn Dòng hiệp sĩ đã dựng sảnh đường trong thế giới rộng lớn, mỗi Dòng phụng sự một vị thần huyền thoại, một Rare Friend có hình dấu hiệu của một chuỗi. Dòng Kim Cương phụng sự Good Friend (xanh như nước sâu, một viên kim cương dựng đứng) ở đồng cỏ Thung lũng Kế; Dòng Mực phụng sự Squid Friend (tím bão tố) trên mũi đất Quillhaven; Dòng Sol phụng sự Weird Friend (mặt trời mọi sắc màu) trên đồi Southshore; Dòng Mũ Trùm phụng sự Hood Friend (xanh lá non) ở Vùng Hoang dã. Tượng các vị thần đứng trước mỗi sảnh và tượng nhỏ trên mỗi bàn thờ.", "Empat Ordo ksatria telah mendirikan balai di dunia yang lebih luas, masing-masing melayani dewa legenda, Rare Friend berbentuk seperti tanda sebuah rantai. Ordo Berlian melayani Good Friend (biru seperti air dalam, berlian berdiri di ujungnya) di padang Lembah Thistle; Ordo Tinta melayani Squid Friend (ungu badai) di tanjung Quillhaven; Ordo Sol melayani Weird Friend (matahari segala warna) di perbukitan Southshore; Ordo Tudung melayani Hood Friend (hijau daun muda) di The Wilds. Patung para dewa berdiri di depan tiap balai dan versi kecilnya di tiap altar.", "ภาคีอัศวินสี่ภาคีตั้งหอในโลกที่กว้างขึ้น แต่ละภาคีรับใช้เทพแห่งตำนาน Rare Friend ที่มีรูปร่างเหมือนสัญลักษณ์ของเชน ภาคีเพชรรับใช้ Good Friend (สีน้ำเงินดั่งน้ำลึก เพชรตั้งปลายแหลม) ในทุ่งหุบเขาทิสเซิล ภาคีหมึกรับใช้ Squid Friend (ม่วงพายุ) บนแหลมควิลเฮเวน ภาคีซอลรับใช้ Weird Friend (ดวงอาทิตย์ทุกสี) บนเนินเซาท์ชอร์ ภาคีฮู้ดรับใช้ Hood Friend (สีเขียวใบไม้อ่อน) ในป่าเถื่อน รูปปั้นเทพตั้งอยู่หน้าหอแต่ละแห่งและรูปเล็กบนแท่นบูชาแต่ละแท่น", "Dört şövalye Tarikatı daha geniş dünyada salonlar kurdu; her biri efsanevi bir tanrıya, bir zincirin işareti biçiminde bir Rare Friend'e hizmet ediyor. Elmas Tarikatı, Devedikeni Vadisi çayırlarında Good Friend'e (derin su mavisi, sivri ucunda bir elmas); Mürekkep Tarikatı, Quillhaven burnunda Squid Friend'e (fırtına moru); Sol Tarikatı, Southshore tepelerinde Weird Friend'e (her renkten bir güneş); Kukuleta Tarikatı, Yabanlar'da Hood Friend'e (taze yaprak yeşili) hizmet ediyor. Tanrıların heykelleri her salonun önünde, küçükleri her sunakta duruyor.", "Cuatro Órdenes de caballería han levantado salones en el mundo más amplio, cada una al servicio de un dios de leyenda, un Rare Friend con forma del símbolo de una cadena. La Orden del Diamante sirve al Good Friend (azul como el agua profunda, un diamante sobre su punta) en los prados de El Valle del Cardo; la Orden de la Tinta sirve al Squid Friend (morado tormenta) en el cabo de Quillhaven; la Orden del Sol sirve al Weird Friend (un sol de todos los colores) en las lomas de Southshore; la Orden de la Capucha sirve al Hood Friend (el verde de las hojas nuevas) en Las Tierras Salvajes. Estatuas de los dioses se alzan ante cada salón y, pequeñas, en cada altar.", "Quatro Ordens de cavalaria ergueram salões no mundo maior, cada uma servindo a um deus lendário, um Rare Friend no formato do símbolo de uma rede. A Ordem do Diamante serve ao Good Friend (azul como água funda, um diamante de ponta) nos prados do Vale do Cardo; a Ordem da Tinta serve ao Squid Friend (roxo de tempestade) no promontório de Quillhaven; a Ordem do Sol serve ao Weird Friend (um sol de todas as cores) nas colinas de Southshore; a Ordem do Capuz serve ao Hood Friend (o verde das folhas novas) nas Terras Selvagens. Estátuas dos deuses ficam diante de cada salão e, pequenas, em cada altar.", "Четыре рыцарских Ордена воздвигли залы в широком мире, и каждый служит богу из легенд — Rare Friend в виде знака одной из сетей. Орден Алмаза служит Good Friend (синий, как глубокая вода, алмаз на острие) на лугах Чертополоховой долины; Орден Чернил — Squid Friend (грозовой фиолетовый) на мысу Квиллхейвена; Орден Сола — Weird Friend (солнце всех цветов) на холмах Саутшора; Орден Капюшона — Hood Friend (зелень молодых листьев) в Дичи. Статуи богов стоят перед каждым залом, а маленькие — на каждом алтаре.", "Чотири лицарські Ордени звели зали в широкому світі, і кожен служить богові з легенд — Rare Friend у вигляді знака однієї з мереж. Орден Діаманта служить Good Friend (синій, як глибока вода, діамант на вістрі) на луках Будякової долини; Орден Чорнила — Squid Friend (грозовий фіолетовий) на мисі Квіллгейвена; Орден Сола — Weird Friend (сонце всіх кольорів) на пагорбах Саутшора; Орден Каптура — Hood Friend (зелень молодого листя) у Дикині. Статуї богів стоять перед кожною залою, а маленькі — на кожному вівтарі."],
  "Swear an Order's oath with its commander (Faith 20; kneel at its altar and bring its gift) and its quartermaster opens the armoury: helm, cuirass, greaves, gauntlets, boots, a kite shield and an aegis, a mace, a greatmace and a staff, in three tiers (Oathbound at Faith 20, Knight at 45, Paladin at 70), all blessed as faith arms and each Order's look its own: Diamond plate, Ink robes, Sol tunics, Hood leathers. Each Order's gear carries its own blessing by the piece: the Diamond turns 2% of a blow aside, the Ink keeps a faith spell's sigils 5% of the time, the Sol adds 4% Faith XP and 1% double blows, the Hood adds 4% to coin drops and 2% to pockets. The oath gives the Order's cape. The Orders' people stand on a new frame, a head taller than the villagers and stout with it.": ["団長のもとで騎士団の誓いを立てる（信仰20、祭壇にひざまずいて捧げ物を持参）と、補給係が武具庫を開きます：兜、胸当て、すね当て、籠手、ブーツ、カイトシールドとイージス、メイス、大メイス、杖を3段階（誓約者は信仰20、騎士は45、聖騎士は70）で。どれも信仰の武具として祝福され、騎士団ごとに見た目が違います：ダイヤモンドは板金鎧、インクはローブ、ソルはチュニック、フードは革。騎士団の装備は部位ごとに独自の祝福を持ちます：ダイヤモンドは攻撃の2%をそらし、インクは信仰の呪文のシジルを5%の確率で温存し、ソルは信仰経験値+4%と1%の連撃、フードはコインのドロップ+4%とスリ+2%。誓いを立てると騎士団のマントがもらえます。騎士団の人々は新しい体型で、村人より頭ひとつ高く、がっしりしています。", "기사단장 앞에서 기사단의 서약을 하면(신앙 20, 제단에 무릎 꿇고 공물을 바침) 보급관이 무기고를 엽니다: 투구, 흉갑, 정강이받이, 건틀릿, 장화, 연 방패와 아이기스, 메이스, 대형 메이스, 지팡이를 세 단계(서약자는 신앙 20, 기사는 45, 성기사는 70)로. 모두 신앙 무구로 축복받았고 기사단마다 모습이 다릅니다: 다이아몬드는 판금, 잉크는 로브, 솔은 튜닉, 후드는 가죽. 기사단 장비는 부위마다 고유한 축복이 있습니다: 다이아몬드는 공격의 2%를 빗겨 내고, 잉크는 신앙 주문의 인장을 5% 확률로 아끼며, 솔은 신앙 경험치 +4%와 1% 연타, 후드는 코인 드롭 +4%와 소매치기 +2%. 서약하면 기사단 망토를 받습니다. 기사단 사람들은 새 체형으로, 마을 사람보다 머리 하나 크고 다부집니다.", "在骑士团团长面前立下誓言（信仰 20；跪于祭坛并献上礼物），军需官就会开放军械库：头盔、胸甲、护胫、护手、靴子、鸢盾和神盾、钉锤、巨型钉锤和法杖，分三个等级（誓约者需信仰 20，骑士 45，圣骑士 70），全部作为信仰武具受过祝福，每个骑士团外观各异：钻石是板甲，墨是长袍，日轮是束腰外衣，兜帽是皮甲。每个骑士团的装备每件都带有自己的祝福：钻石偏转 2% 的攻击，墨有 5% 几率保留信仰法术的印记，日轮增加 4% 信仰经验和 1% 连击，兜帽增加 4% 金币掉落和 2% 扒窃收获。立誓会获得骑士团披风。骑士团的人用上了新体型，比村民高一个头，也更壮实。", "在騎士團團長面前立下誓言（信仰 20；跪於祭壇並獻上禮物），軍需官就會開放軍械庫：頭盔、胸甲、護脛、護手、靴子、鳶盾和神盾、釘錘、巨型釘錘和法杖，分三個等級（誓約者需信仰 20，騎士 45，聖騎士 70），全部作為信仰武具受過祝福，每個騎士團外觀各異：鑽石是板甲，墨是長袍，日輪是束腰外衣，兜帽是皮甲。每個騎士團的裝備每件都帶有自己的祝福：鑽石偏轉 2% 的攻擊，墨有 5% 機率保留信仰法術的印記，日輪增加 4% 信仰經驗和 1% 連擊，兜帽增加 4% 金幣掉落和 2% 扒竊收穫。立誓會獲得騎士團披風。騎士團的人用上了新體型，比村民高一個頭，也更壯實。", "Tuyên thệ với chỉ huy của một Dòng (Đức tin 20; quỳ ở bàn thờ và mang lễ vật) và quân nhu sẽ mở kho vũ khí: mũ giáp, giáp ngực, giáp chân, găng giáp, ủng, khiên diều và khiên thánh, chùy, đại chùy và gậy phép, theo ba bậc (Thệ Ước ở Đức tin 20, Hiệp sĩ ở 45, Thánh Kỵ Sĩ ở 70), tất cả được ban phước như vũ khí đức tin và mỗi Dòng một vẻ riêng: giáp tấm Kim Cương, áo choàng Mực, áo chẽn Sol, đồ da Mũ Trùm. Trang bị mỗi Dòng mang phước lành riêng theo từng món: Kim Cương đỡ 2% mỗi đòn, Mực giữ ấn của phép đức tin 5% số lần, Sol thêm 4% XP Đức tin và 1% đòn kép, Mũ Trùm thêm 4% xu rơi và 2% móc túi. Lời thề cho áo choàng của Dòng. Người của các Dòng có vóc dáng mới, cao hơn dân làng một cái đầu và vạm vỡ.", "Ucapkan sumpah Ordo di hadapan komandannya (Iman 20; berlutut di altarnya dan bawa persembahannya) dan juru perbekalannya membuka gudang senjata: helm, zirah dada, pelindung kaki, sarung tangan zirah, sepatu bot, perisai layang dan aegis, gada, gada besar, dan tongkat, dalam tiga tingkat (Tersumpah di Iman 20, Ksatria di 45, Paladin di 70), semuanya diberkati sebagai senjata iman dan setiap Ordo punya tampilannya sendiri: zirah pelat Berlian, jubah Tinta, tunik Sol, kulit Tudung. Perlengkapan tiap Ordo membawa berkahnya sendiri per bagian: Berlian menangkis 2% pukulan, Tinta menyimpan sigil mantra iman 5% waktu, Sol menambah 4% XP Iman dan 1% pukulan ganda, Tudung menambah 4% jatuhan koin dan 2% hasil copet. Sumpahnya memberi mantel Ordo. Orang-orang Ordo berdiri pada perawakan baru, sekepala lebih tinggi dari warga desa dan gempal.", "สาบานตนกับผู้บัญชาการของภาคี (ศรัทธา 20 คุกเข่าที่แท่นบูชาและนำของถวายมา) แล้วผู้จัดหาเสบียงจะเปิดคลังอาวุธ: หมวกเกราะ เกราะอก สนับแข้ง ถุงมือเกราะ รองเท้าบูต โล่ว่าวและอีจิส กระบอง กระบองใหญ่ และคทา สามระดับ (ผู้ถือสัตย์ที่ศรัทธา 20 อัศวินที่ 45 พาลาดินที่ 70) ทั้งหมดได้รับพรเป็นอาวุธศรัทธาและแต่ละภาคีมีลุคของตัวเอง: เกราะแผ่นเพชร เสื้อคลุมหมึก ทูนิกซอล หนังฮู้ด อุปกรณ์แต่ละภาคีมีพรของตัวเองทุกชิ้น: เพชรปัด 2% ของการโจมตี หมึกเก็บผนึกของคาถาศรัทธาไว้ 5% ซอลเพิ่ม XP ศรัทธา 4% และโจมตีสองครั้ง 1% ฮู้ดเพิ่มเหรียญดรอป 4% และล้วงกระเป๋า 2% คำสาบานให้ผ้าคลุมของภาคี คนของภาคียืนบนร่างแบบใหม่ สูงกว่าชาวบ้านหนึ่งหัวและบึกบึน", "Bir Tarikat'ın yeminini komutanıyla et (İnanç 20; sunağında diz çök ve armağanını getir) ve levazımcısı cephaneliği açar: miğfer, göğüslük, dizlikler, eldivenler, botlar, bir uçurtma kalkan ve bir egis, bir gürz, büyük bir gürz ve bir asa; üç kademede (İnanç 20'de Yeminli, 45'te Şövalye, 70'te Paladin), hepsi inanç silahı olarak kutsanmış ve her Tarikat'ın görünüşü kendine özgü: Elmas plakası, Mürekkep cüppeleri, Sol tunikleri, Kukuleta derileri. Her Tarikat'ın teçhizatı parça başına kendi kutsamasını taşır: Elmas bir darbenin %2'sini saptırır, Mürekkep bir inanç büyüsünün mühürlerini %5 ihtimalle saklar, Sol %4 İnanç XP'si ve %1 çift vuruş ekler, Kukuleta para düşüşlerine %4 ve yankesiciliğe %2 ekler. Yemin, Tarikat'ın pelerinini verir. Tarikatların insanları yeni bir bedende; köylülerden bir baş uzun ve iri yapılı.", "Jura el juramento de una Orden ante su comandante (Fe 20; arrodíllate en su altar y lleva su ofrenda) y su intendente te abre la armería: yelmo, coraza, grebas, guanteletes, botas, un escudo de cometa y una égida, una maza, una gran maza y un bastón, en tres niveles (Juramentado con Fe 20, Caballero con 45, Paladín con 70), todos bendecidos como armas de fe y cada Orden con su aspecto: placas del Diamante, túnicas de la Tinta, sayos del Sol, cueros de la Capucha. El equipo de cada Orden lleva su propia bendición por pieza: el Diamante desvía un 2 % de cada golpe, la Tinta conserva los sigilos de un hechizo de fe un 5 % de las veces, el Sol suma un 4 % de XP de Fe y un 1 % de golpes dobles, la Capucha suma un 4 % a las monedas soltadas y un 2 % a los bolsillos. El juramento da la capa de la Orden. La gente de las Órdenes tiene una figura nueva, una cabeza más alta que los aldeanos y robusta.", "Faça o juramento de uma Ordem com seu comandante (Fé 20; ajoelhe no altar e leve a oferenda) e o intendente abre o arsenal: elmo, couraça, grevas, manoplas, botas, um escudo de pipa e uma égide, uma maça, uma grande maça e um cajado, em três níveis (Juramentado na Fé 20, Cavaleiro no 45, Paladino no 70), todos abençoados como armas de fé e cada Ordem com seu visual: placas do Diamante, mantos da Tinta, túnicas do Sol, couros do Capuz. O equipamento de cada Ordem carrega sua própria bênção por peça: o Diamante desvia 2% de um golpe, a Tinta guarda os sigilos de um feitiço de fé 5% das vezes, o Sol soma 4% de XP de Fé e 1% de golpes duplos, o Capuz soma 4% às moedas soltas e 2% aos bolsos. O juramento dá a capa da Ordem. O povo das Ordens tem um corpo novo, uma cabeça mais alto que os aldeões e robusto.", "Принесите клятву Ордена его командору (Вера 20; преклоните колени у алтаря и принесите дар), и интендант откроет оружейную: шлем, кираса, поножи, латные перчатки, сапоги, каплевидный щит и эгида, булава, большая булава и посох — трёх уровней (Присягнувший на Вере 20, Рыцарь на 45, Паладин на 70), всё освящено как оружие веры, и у каждого Ордена свой облик: латы Алмаза, мантии Чернил, туники Сола, кожа Капюшона. У снаряжения каждого Ордена своё благословение за каждый предмет: Алмаз отводит 2% удара, Чернила в 5% случаев сохраняют печати заклинания веры, Сол даёт +4% опыта Веры и 1% двойных ударов, Капюшон — +4% к выпадению монет и +2% к карманным кражам. Клятва даёт плащ Ордена. Люди Орденов стоят на новом теле — на голову выше селян и крепкого сложения.", "Складіть присягу Ордену перед його командором (Віра 20; станьте на коліна біля вівтаря й принесіть дар), і інтендант відчинить зброярню: шолом, кіраса, наголінники, латні рукавиці, чоботи, мигдалеподібний щит і егіда, булава, велика булава й посох — трьох рівнів (Присяжний на Вірі 20, Лицар на 45, Паладин на 70), усе освячене як зброя віри, і в кожного Ордену свій вигляд: лати Діаманта, мантії Чорнила, туніки Сола, шкіра Каптура. Спорядження кожного Ордену має своє благословення за кожен предмет: Діамант відводить 2% удару, Чорнило в 5% випадків зберігає печатки заклинання віри, Сол дає +4% досвіду Віри та 1% подвійних ударів, Каптур — +4% до випадіння монет і +2% до кишенькових крадіжок. Присяга дає плащ Ордену. Люди Орденів стоять на новому тілі — на голову вищі за селян і кремезні."],
  "A fifth Order, the Order of the Ember, holds a fortress at Ashfall on an island of ash inside a moat of lava, a causeway of blackened stone to its gate and drakes circling it. It serves no god but the flame in its brazier; its oath takes three wyrm scales, and every piece of its ember-red plate turns 5% of dragonfire aside.": ["5番目の騎士団、エンバー教団は、アッシュフォールの溶岩の堀に囲まれた灰の島に要塞を構えています。門へは黒焦げの石の土手道が続き、ドレイクが上空を旋回しています。仕えるのは神ではなく火鉢の炎だけ。誓いにはワームの鱗3枚が必要で、残り火色の板金鎧はどの部位も竜の炎の5%をそらします。", "다섯째 기사단, 불씨 기사단은 애시폴의 용암 해자 안 잿더미 섬에 요새를 두고 있습니다. 문까지 검게 그을린 돌 둑길이 이어지고, 드레이크가 그 위를 맴돕니다. 섬기는 신은 없고 화로의 불꽃뿐입니다. 서약엔 용의 비늘 셋이 필요하고, 불씨빛 판금 갑옷은 부위마다 용의 불길 5%를 빗겨 냅니다.", "第五个骑士团，余烬骑士团，在灰落的熔岩护城河中一座灰烬岛上据守要塞，一条焦黑的石堤道通往城门，幼龙在上空盘旋。它不侍奉任何神，只侍奉火盆里的火焰；立誓需要三片龙鳞片，它的余烬红板甲每一件都能偏转 5% 的龙火。", "第五個騎士團，餘燼騎士團，在灰落的熔岩護城河中一座灰燼島上據守要塞，一條焦黑的石堤道通往城門，幼龍在上空盤旋。它不侍奉任何神，只侍奉火盆裡的火焰；立誓需要三片龍鱗片，它的餘燼紅板甲每一件都能偏轉 5% 的龍火。", "Dòng thứ năm, Dòng Than Hồng, giữ một pháo đài ở Ashfall trên hòn đảo tro giữa hào dung nham, một con đường đá cháy đen dẫn đến cổng và rồng con lượn quanh. Nó không phụng sự thần nào ngoài ngọn lửa trong lò than; lời thề cần ba vảy rồng, và mỗi món giáp tấm đỏ than hồng của nó đỡ được 5% lửa rồng.", "Ordo kelima, Ordo Bara, menguasai benteng di Ashfall di pulau abu di dalam parit lava, jalan batu hangus menuju gerbangnya dan drake berputar di atasnya. Ia tak melayani dewa selain api di anglonya; sumpahnya butuh tiga sisik naga, dan setiap bagian zirah pelat merah baranya menangkis 5% api naga.", "ภาคีที่ห้า ภาคีถ่านไฟ ครองป้อมที่แอชฟอลล์บนเกาะเถ้ากลางคูลาวา ทางหินดำไหม้ทอดไปยังประตูและมังกรน้อยบินวนรอบ มันไม่รับใช้เทพใดนอกจากเปลวไฟในกระถาง คำสาบานต้องใช้เกล็ดมังกรสามชิ้น และเกราะแผ่นสีแดงถ่านไฟทุกชิ้นปัดไฟมังกรได้ 5%", "Beşinci bir Tarikat, Kor Tarikatı, Ashfall'da lav dolu bir hendeğin içindeki kül adasında bir kale tutuyor; kapısına kararmış taştan bir yol gidiyor ve ejderyalar etrafında dönüyor. Mangalındaki alevden başka hiçbir tanrıya hizmet etmiyor; yemini üç ejder pulu ister ve kor kırmızısı plaka zırhının her parçası ejder ateşinin %5'ini saptırır.", "Una quinta Orden, la Orden de la Brasa, tiene una fortaleza en Ashfall sobre una isla de ceniza dentro de un foso de lava, con una calzada de piedra ennegrecida hasta su puerta y dracos volando en círculos. No sirve a ningún dios salvo a la llama de su brasero; su juramento pide tres escamas de sierpe, y cada pieza de su armadura de placas rojo brasa desvía un 5 % del fuego de dragón.", "Uma quinta Ordem, a Ordem da Brasa, mantém uma fortaleza em Ashfall numa ilha de cinza dentro de um fosso de lava, com uma calçada de pedra enegrecida até o portão e dracos circulando. Não serve a deus algum além da chama do seu braseiro; o juramento pede três escamas de serpe, e cada peça da sua armadura de placas vermelho-brasa desvia 5% do fogo de dragão.", "Пятый Орден, Орден Жара, держит крепость в Эшфолле на пепельном острове посреди лавового рва: к воротам ведёт дамба из почерневшего камня, над ней кружат дрейки. Он служит не богу, а пламени своей жаровни; для клятвы нужны три змеиные чешуи, а каждый предмет его угольно-красных лат отводит 5% драконьего огня.", "П'ятий Орден, Орден Жару, тримає фортецю в Ешфоллі на попелястому острові посеред лавового рову: до брами веде гребля з почорнілого каменю, над нею кружляють дрейки. Він служить не богові, а полум'ю своєї жаровні; для присяги потрібні три зміїні луски, а кожен предмет його жаристо-червоних лат відводить 5% драконячого вогню."],
  "A ring slot in your worn equipment, and the first ring to fill it: the Ringmaster's signet, from Ringmaster Vell Harrow once you've won three matches (thirty bloodmarks for the stamping). It lends +4 Strength, and rubbed anywhere in the Realm it carries you to the Ring's lobby, three times a day (the day turns at midnight UTC).": ["装備に指輪枠が追加され、最初の指輪も登場：リングマスターの印章指輪。3試合に勝つとリングマスター ヴェル・ハロウからもらえます（刻印に血の印30）。筋力+4を与え、レルムのどこでもこすればリングのロビーへ運んでくれます（1日3回、日付は UTC の午前0時で変わります）。", "착용 장비에 반지 칸이 생겼고, 첫 반지도 나왔습니다: 링마스터의 인장 반지. 경기를 세 번 이기면 링마스터 벨 해로에게 받습니다(각인에 핏자국 30). 힘 +4를 주고, 렐름 어디서든 문지르면 링 로비로 데려다줍니다(하루 세 번, 날짜는 UTC 자정에 바뀝니다).", "装备中新增戒指栏，第一枚戒指也来了：擂台主印戒，赢下三场比赛后由擂台主维尔·哈罗授予（盖印需三十血印）。它提供 +4 力量，在王国任何地方摩擦它都能把你送到擂台大厅，每天三次（每天在 UTC 午夜更新）。", "裝備中新增戒指欄，第一枚戒指也來了：擂台主印戒，贏下三場比賽後由擂台主維爾·哈羅授予（蓋印需三十血印）。它提供 +4 力量，在王國任何地方摩擦它都能把你送到擂台大廳，每天三次（每天在 UTC 午夜更新）。", "Một ô nhẫn trong trang bị, và chiếc nhẫn đầu tiên để đeo: Nhẫn ấn của Chủ đấu trường, từ Chủ đấu trường Vell Harrow khi bạn thắng ba trận (ba mươi dấu máu cho việc đóng dấu). Nó cho +4 Sức mạnh, và xoa nó ở bất cứ đâu trong Vương quốc sẽ đưa bạn đến sảnh Đấu trường, ba lần mỗi ngày (ngày mới bắt đầu lúc nửa đêm UTC).", "Slot cincin di perlengkapan yang dipakai, dan cincin pertama untuk mengisinya: Cincin segel Pemimpin Ring, dari Pemimpin Ring Vell Harrow setelah kau memenangkan tiga pertandingan (tiga puluh tanda darah untuk pengecapannya). Memberi +4 Kekuatan, dan bila digosok di mana pun di Realm membawamu ke lobi Ring, tiga kali sehari (hari berganti pada tengah malam UTC).", "ช่องแหวนในอุปกรณ์ที่สวม และแหวนวงแรก: แหวนตราผู้คุมสังเวียน จากผู้คุมสังเวียนเวลล์ แฮร์โรว์เมื่อชนะสามแมตช์ (รอยเลือดสามสิบสำหรับการประทับตรา) ให้พลัง +4 และถูที่ไหนในอาณาจักรก็พาคุณไปล็อบบี้สังเวียนได้ วันละสามครั้ง (วันเปลี่ยนตอนเที่ยงคืน UTC)", "Giyilen teçhizatta bir yüzük yuvası ve onu dolduracak ilk yüzük: Ring ustasının mühür yüzüğü; üç maç kazandıktan sonra Ring Ustası Vell Harrow'dan (damgası için otuz kan izi). +4 Güç verir ve Diyar'ın herhangi bir yerinde ovulduğunda seni günde üç kez Ring'in lobisine taşır (gün UTC gece yarısı döner).", "Un hueco de anillo en tu equipo, y el primer anillo para llenarlo: el Sello del maestro del Ring, del Maestro del Ring Vell Harrow cuando hayas ganado tres combates (treinta marcas de sangre por el sellado). Da +4 de Fuerza y, frotado en cualquier lugar del Reino, te lleva al vestíbulo del Ring tres veces al día (el día cambia a medianoche UTC).", "Um espaço de anel no equipamento, e o primeiro anel para ocupá-lo: o Sinete do mestre do Ringue, do Mestre do Ringue Vell Harrow depois que você vence três lutas (trinta marcas de sangue pela gravação). Dá +4 de Força e, esfregado em qualquer lugar do Reino, leva você ao saguão do Ringue, três vezes por dia (o dia vira à meia-noite UTC).", "Слот кольца в снаряжении и первое кольцо для него: перстень распорядителя Ринга, от распорядителя Велла Харроу после трёх выигранных матчей (тридцать кровавых меток за чеканку). Даёт +4 к Силе, а если потереть его в любом месте Королевства, переносит в вестибюль Ринга — трижды в день (день сменяется в полночь UTC).", "Слот персня в спорядженні й перший перстень для нього: перстень розпорядника Рингу, від розпорядника Велла Гарроу після трьох виграних матчів (тридцять кривавих міток за карбування). Дає +4 до Сили, а якщо потерти його будь-де в Королівстві, переносить у вестибюль Рингу — тричі на день (день змінюється опівночі UTC)."],
  "Deep in the east of the Deadwood the Deadwood Maidens hold a fenced camp, and they hold it against everyone: their spearwomen attack on sight. Matriarch Ysolde Thornveil will talk; keep her truce (put ten of the Deadwood's dead down in the east of the wood, bring twelve grave dust and four crypt bones) and the spears stay down, you wear the Maiden's veil, and Wren's market opens: rarite ore, Hollow essence, gloom shards, wyrm scales, cinder cores, crystal shards, grave dust, pages, the rarer sigils, and a key to every locked door in the Realm.": ["Deadwood の東の奥深くで枯れ森の乙女たちが柵で囲った野営地を守っていて、誰に対しても守り抜きます：槍を持つ女たちは見つけ次第攻撃してきます。女家長イゾルデ・ソーンヴェイルは話を聞いてくれます。彼女の休戦を守れば（森の東で Deadwood の死者を10体眠らせ、墓の塵12と地下墓所の骨4を持ってくる）、槍は下ろされ、乙女のヴェールを身につけられ、Wren の市場が開きます：レアライト鉱石、虚ろの精髄、闇の欠片、ワームの鱗、燃えさしの核、水晶の欠片、墓の塵、紙片、珍しいシジル、そしてレルムのすべての鍵のかかった扉の鍵。", "Deadwood 동쪽 깊숙이 데드우드의 처녀들이 울타리 친 야영지를 지키며, 누구에게서든 지켜 냅니다: 창을 든 여인들이 보자마자 공격합니다. 가모장 이졸데 손베일은 이야기를 나눕니다. 그녀의 휴전을 지키면(숲 동쪽에서 Deadwood의 망자 열을 쓰러뜨리고, 무덤 먼지 열둘과 지하묘지 뼈 넷을 가져오기) 창이 내려가고, 처녀의 면사포를 쓰게 되며, Wren의 시장이 열립니다: 레어라이트 광석, 공허의 정수, 어둠 조각, 용의 비늘, 잿불 핵, 수정 조각, 무덤 먼지, 종이, 희귀한 인장, 그리고 렐름의 모든 잠긴 문 열쇠.", "在 Deadwood 东部深处，枯木少女们守着一座围栏营地，对谁都寸步不让：她们的持矛女战士见人就攻。女族长伊索尔德·棘纱愿意交谈；遵守她的休战协议（在林子东部让十个 Deadwood 的亡者安息，带来十二份墓尘和四块墓穴骨头），长矛就会放下，你可以戴上少女面纱，Wren 的市集也会开张：稀晶矿石、虚空精华、幽暗碎片、龙鳞片、余烬之核、水晶碎片、墓尘、书页、较稀有的印记，以及王国中每扇锁着的门的钥匙。", "在 Deadwood 東部深處，枯木少女們守著一座圍欄營地，對誰都寸步不讓：她們的持矛女戰士見人就攻。女族長伊索爾德·棘紗願意交談；遵守她的休戰協議（在林子東部讓十個 Deadwood 的亡者安息，帶來十二份墓塵和四塊墓穴骨頭），長矛就會放下，你可以戴上少女面紗，Wren 的市集也會開張：稀晶礦石、虛空精華、幽暗碎片、龍鱗片、餘燼之核、水晶碎片、墓塵、書頁、較稀有的印記，以及王國中每扇鎖著的門的鑰匙。", "Sâu trong phía đông Deadwood, các Thiếu nữ Deadwood giữ một trại có rào, và họ giữ nó trước mọi người: các nữ chiến binh giáo tấn công ngay khi thấy. Nữ tộc trưởng Ysolde Thornveil sẽ nói chuyện; giữ thỏa thuận ngừng chiến của bà (hạ mười người chết của Deadwood ở phía đông khu rừng, mang mười hai bụi mộ và bốn xương hầm mộ) thì giáo sẽ hạ xuống, bạn đeo Mạng che mặt thiếu nữ, và chợ của Wren mở cửa: quặng rarit, tinh chất hư không, mảnh u ám, vảy rồng, lõi than hồng, mảnh pha lê, bụi mộ, trang giấy, các ấn hiếm hơn, và chìa khóa cho mọi cánh cửa khóa trong Vương quốc.", "Jauh di timur Deadwood, Gadis Deadwood menjaga perkemahan berpagar, dan menjaganya dari siapa pun: para wanita bertombak menyerang begitu melihat. Matriark Ysolde Thornveil mau bicara; jaga gencatan senjatanya (tumbangkan sepuluh orang mati Deadwood di timur hutan, bawa dua belas debu kubur dan empat tulang kripta) dan tombak tetap turun, kau memakai Cadar gadis, dan pasar Wren terbuka: bijih rarit, esensi hampa, serpihan kelam, sisik naga, inti bara, serpihan kristal, debu kubur, halaman, sigil yang lebih langka, dan kunci untuk setiap pintu terkunci di Realm.", "ลึกเข้าไปทางตะวันออกของ Deadwood หญิงสาวป่าไม้ตายครองค่ายที่มีรั้ว และพวกนางป้องกันมันจากทุกคน: นักรบหญิงถือหอกโจมตีทันทีที่เห็น หัวหน้าตระกูลอีโซลด์ ธอร์นเวลจะยอมคุย รักษาสัญญาสงบศึกของนาง (ล้มคนตายของ Deadwood สิบตนทางตะวันออกของป่า นำฝุ่นหลุมศพสิบสองและกระดูกห้องใต้ดินสี่มา) แล้วหอกจะไม่ยกขึ้น คุณได้สวมผ้าคลุมหน้าหญิงสาว และตลาดของ Wren จะเปิด: แร่แรไรต์ แก่นความว่างเปล่า เศษความมืด เกล็ดมังกร แกนถ่านไฟ เศษคริสตัล ฝุ่นหลุมศพ หน้ากระดาษ ผนึกที่หายากกว่า และกุญแจสำหรับประตูที่ล็อกทุกบานในอาณาจักร", "Deadwood'un doğusunun derinliklerinde Deadwood Bakireleri çitle çevrili bir kamp tutuyor ve onu herkese karşı koruyor: mızraklı kadınları görür görmez saldırıyor. Ana Reis Ysolde Thornveil konuşur; ateşkesine uy (ormanın doğusunda Deadwood'un ölülerinden onunu yere ser, on iki mezar tozu ve dört mahzen kemiği getir) ve mızraklar aşağıda kalır, Bakire peçesini takarsın ve Wren'in pazarı açılır: rarit cevheri, Boşluk özü, kasvet parçaları, ejder pulları, kor çekirdekleri, kristal parçaları, mezar tozu, sayfalar, daha nadir mühürler ve Diyar'daki her kilitli kapının anahtarı.", "En lo hondo del este del Deadwood, las Doncellas de Deadwood tienen un campamento vallado, y lo defienden de todos: sus lanceras atacan nada más verte. La matriarca Ysolde Thornveil sí habla; respeta su tregua (abate a diez muertos del Deadwood en el este del bosque, lleva doce de polvo de tumba y cuatro huesos de cripta) y las lanzas se quedan bajas, llevas el Velo de doncella y se abre el mercado de Wren: mineral de rarita, esencia hueca, fragmentos lóbregos, escamas de sierpe, núcleos de ceniza, fragmentos de cristal, polvo de tumba, páginas, los sigilos más raros y una llave para cada puerta cerrada del Reino.", "No fundo do leste do Deadwood, as Donzelas de Deadwood mantêm um acampamento cercado, e o defendem de todo mundo: as lanceiras atacam assim que veem você. A matriarca Ysolde Thornveil conversa; respeite a trégua dela (derrube dez mortos do Deadwood no leste da mata, traga doze de pó de túmulo e quatro ossos de cripta) e as lanças ficam abaixadas, você usa o Véu de donzela e o mercado de Wren abre: minério de rarita, essência oca, fragmentos sombrios, escamas de serpe, núcleos de brasa, fragmentos de cristal, pó de túmulo, páginas, os sigilos mais raros e uma chave para cada porta trancada do Reino.", "В глубине востока Deadwood Девы Мёртвого леса держат огороженный лагерь и держат его против всех: их копейщицы нападают, едва завидев. Матриарх Изольда Тернвейл готова говорить; соблюдите её перемирие (уложите десятерых мертвецов Deadwood на востоке леса, принесите двенадцать могильной пыли и четыре кости из склепа) — и копья останутся опущены, вы наденете Вуаль девы, и откроется рынок Wren: руда рарита, эссенция пустоты, сумрачные осколки, змеиная чешуя, тлеющие ядра, хрустальные осколки, могильная пыль, страницы, редкие печати и ключ от любой запертой двери Королевства.", "У глибині сходу Deadwood Діви Мертвого лісу тримають обгороджений табір і тримають його проти всіх: їхні списниці нападають, щойно побачать. Матріарх Ізольда Тернвейл готова говорити; дотримайтеся її перемир'я (покладіть десятьох мерців Deadwood на сході лісу, принесіть дванадцять могильного пилу й чотири кістки зі склепу) — і списи лишаться опущені, ви вдягнете Вуаль діви, і відкриється ринок Wren: руда рариту, есенція порожнечі, сутінкові уламки, зміїна луска, жевріючі ядра, кришталеві уламки, могильний пил, сторінки, рідкісні печатки й ключ від будь-яких замкнених дверей Королівства."],
  "The Pilgrim's Road runs further": ["巡礼の道はさらに先へ", "순례자의 길이 더 멀리 이어집니다", "朝圣之路延伸得更远", "朝聖之路延伸得更遠", "Con đường hành hương dài thêm", "Jalan Peziarah makin jauh", "เส้นทางผู้แสวงบุญทอดไกลขึ้น", "Hacı Yolu daha uzağa gidiyor", "El camino del peregrino llega más lejos", "A Estrada do Peregrino vai mais longe", "Дорога паломника ведёт дальше", "Дорога прочанина веде далі"],
  "Five wayward chapels of the Order stand in the far places now: one out in the Westmarch, one on the Drakespine among the dragons, one in the Ironreach snows, one in The Wilds, and a great ruined one in the Deadwood, its roof gone and its walls down, graves at its feet. Each has an altar under an Old Friend.": ["騎士団の辺境の礼拝堂が5つ、遠い地に立つようになりました：Westmarch に1つ、ドラゴンのいる Drakespine に1つ、アイアンリーチの雪原に1つ、荒野に1つ、そして Deadwood には屋根も壁も崩れ、足元に墓が並ぶ大きな廃礼拝堂。どれにも古き友の像の下に祭壇があります。", "기사단의 외딴 예배당 다섯이 이제 먼 곳에 서 있습니다: Westmarch에 하나, 드래곤들 사이 Drakespine에 하나, 아이언리치 설원에 하나, 황야에 하나, 그리고 Deadwood에 지붕이 사라지고 벽이 무너진 채 발치에 무덤이 있는 거대한 폐허 예배당. 모두 옛 친구 석상 아래 제단이 있습니다.", "骑士团的五座偏远礼拜堂现在立于远方：一座在 Westmarch，一座在巨龙出没的 Drakespine，一座在铁境的雪原，一座在荒野，还有一座在 Deadwood 的巨大废墟礼拜堂，屋顶没了，墙也塌了，脚下是坟墓。每座都有一座立在故友像下的祭坛。", "騎士團的五座偏遠禮拜堂現在立於遠方：一座在 Westmarch，一座在巨龍出沒的 Drakespine，一座在鐵境的雪原，一座在荒野，還有一座在 Deadwood 的巨大廢墟禮拜堂，屋頂沒了，牆也塌了，腳下是墳墓。每座都有一座立在故友像下的祭壇。", "Năm nhà nguyện hẻo lánh của Dòng giờ đứng ở những nơi xa: một ở Westmarch, một trên Drakespine giữa bầy rồng, một trong tuyết Ironreach, một ở Vùng Hoang dã, và một nhà nguyện đổ nát lớn ở Deadwood, mất mái và sập tường, mộ dưới chân. Mỗi nơi có một bàn thờ dưới tượng Người Bạn Cũ.", "Lima kapel terpencil Ordo kini berdiri di tempat-tempat jauh: satu di Westmarch, satu di Drakespine di antara para naga, satu di salju Ironreach, satu di The Wilds, dan satu kapel reruntuhan besar di Deadwood, atapnya hilang dan dindingnya runtuh, kuburan di kakinya. Masing-masing punya altar di bawah Sahabat Lama.", "โบสถ์ห่างไกลห้าแห่งของภาคีตอนนี้ตั้งอยู่ในที่ไกลๆ: หนึ่งแห่งใน Westmarch หนึ่งแห่งบน Drakespine ท่ามกลางมังกร หนึ่งแห่งในหิมะไอรอนรีช หนึ่งแห่งในป่าเถื่อน และโบสถ์ร้างหลังใหญ่ใน Deadwood หลังคาหายและกำแพงพัง มีหลุมศพอยู่ที่ฐาน แต่ละแห่งมีแท่นบูชาใต้สหายเก่า", "Tarikat'ın beş ücra şapeli artık uzak yerlerde duruyor: biri Westmarch'ta, biri ejderhaların arasında Drakespine'da, biri Ironreach karlarında, biri Yabanlar'da ve Deadwood'da çatısı gitmiş, duvarları yıkılmış, dibinde mezarlar olan büyük yıkık bir şapel. Her birinde Eski Dost'un altında bir sunak var.", "Cinco capillas remotas de la Orden se alzan ahora en lugares lejanos: una en Westmarch, otra en Drakespine entre los dragones, otra en las nieves de Ironreach, otra en Las Tierras Salvajes y una gran capilla en ruinas en el Deadwood, sin tejado y con los muros caídos, con tumbas a sus pies. Cada una tiene un altar bajo un Viejo Amigo.", "Cinco capelas remotas da Ordem ficam agora em lugares distantes: uma em Westmarch, uma em Drakespine entre os dragões, uma na neve de Ironreach, uma nas Terras Selvagens e uma grande capela em ruínas no Deadwood, sem telhado e com as paredes caídas, túmulos aos pés. Cada uma tem um altar sob um Velho Amigo.", "Пять отдалённых часовен Ордена стоят теперь в дальних краях: одна в Westmarch, одна на Drakespine среди драконов, одна в снегах Айронрича, одна в Дичи и большая разрушенная в Deadwood — без крыши, с рухнувшими стенами и могилами у подножия. В каждой алтарь под Старым Другом.", "П'ять віддалених каплиць Ордену стоять тепер у далеких краях: одна в Westmarch, одна на Drakespine серед драконів, одна в снігах Айронріча, одна в Дикині й велика зруйнована в Deadwood — без даху, з обваленими стінами й могилами біля підніжжя. У кожній вівтар під Старим Другом."],
  "The Pilgrim's Road takes in all of them: eight altars now, three old and five wayward, and Sister Maren's thanks have grown to match (9,000 Faith XP and 2,500 Wayfaring XP with the Dawnplate greaves and boots).": ["巡礼の道はそのすべてを巡ります：祭壇は古い3つと辺境の5つで計8つになり、シスター・マーレンのお礼もそれに見合うだけ増えました（信仰経験値9,000と旅路経験値2,500、Dawnplate のすね当てとブーツ付き）。", "순례자의 길이 그 모두를 거칩니다: 이제 제단 여덟, 옛것 셋과 외딴 것 다섯이고, 마렌 수녀의 감사도 그만큼 커졌습니다(신앙 경험치 9,000과 여행 경험치 2,500, Dawnplate 정강이받이와 장화).", "朝圣之路把它们全都包括在内：现在共有八座祭坛，三座古老的和五座偏远的，玛伦修女的谢礼也相应增加了（9,000 信仰经验和 2,500 行旅经验，外加 Dawnplate 护胫和靴子）。", "朝聖之路把它們全都包括在內：現在共有八座祭壇，三座古老的和五座偏遠的，瑪倫修女的謝禮也相應增加了（9,000 信仰經驗和 2,500 行旅經驗，外加 Dawnplate 護脛和靴子）。", "Con đường hành hương đi qua tất cả: giờ là tám bàn thờ, ba cũ và năm hẻo lánh, và lời cảm ơn của Sơ Maren cũng lớn tương xứng (9.000 XP Đức tin và 2.500 XP Lữ hành cùng giáp chân và ủng Dawnplate).", "Jalan Peziarah mencakup semuanya: kini delapan altar, tiga lama dan lima terpencil, dan terima kasih Suster Maren bertambah sepadan (9.000 XP Iman dan 2.500 XP Pengembaraan dengan pelindung kaki dan sepatu bot Dawnplate).", "เส้นทางผู้แสวงบุญรวมทั้งหมดไว้: ตอนนี้มีแท่นบูชาแปดแห่ง เก่าสามและห่างไกลห้า และคำขอบคุณของซิสเตอร์มาเรนก็เพิ่มขึ้นตาม (XP ศรัทธา 9,000 และ XP การเดินทาง 2,500 พร้อมสนับแข้งและรองเท้าบูต Dawnplate)", "Hacı Yolu hepsini kapsıyor: artık sekiz sunak, üçü eski beşi ücra ve Rahibe Maren'in teşekkürü de buna göre büyüdü (Dawnplate dizlikleri ve botlarıyla 9.000 İnanç XP'si ve 2.500 Yolculuk XP'si).", "El camino del peregrino pasa ahora por todas: ocho altares, tres antiguos y cinco remotos, y el agradecimiento de la hermana Maren ha crecido a la par (9.000 de XP de Fe y 2.500 de XP de Andanzas con las grebas y botas de Dawnplate).", "A Estrada do Peregrino passa por todas: agora são oito altares, três antigos e cinco remotos, e o agradecimento da Irmã Maren cresceu à altura (9.000 de XP de Fé e 2.500 de XP de Andanças com as grevas e botas de Dawnplate).", "Дорога паломника охватывает их все: теперь восемь алтарей, три старых и пять отдалённых, и благодарность сестры Марен выросла соответственно (9000 опыта Веры и 2500 опыта Странствий вместе с поножами и сапогами Dawnplate).", "Дорога прочанина охоплює їх усі: тепер вісім вівтарів, три старі й п'ять віддалених, і подяка сестри Марен зросла відповідно (9000 досвіду Віри й 2500 досвіду Мандрів разом із наголінниками й чоботами Dawnplate)."],
  "Two dungeons for the rest of us, and capes and shields that sit right": ["みんなのためのダンジョン2つと、きちんと収まるマントと盾", "모두를 위한 던전 둘, 그리고 제대로 맞는 망토와 방패", "适合大家的两座地下城，以及穿戴得体的披风和盾牌", "適合大家的兩座地下城，以及穿戴得體的披風和盾牌", "Hai hầm ngục cho mọi người, và áo choàng cùng khiên nằm đúng chỗ", "Dua ruang bawah tanah untuk kita semua, dan jubah serta perisai yang pas", "ดันเจี้ยนสองแห่งสำหรับพวกเราที่เหลือ และผ้าคลุมกับโล่ที่อยู่ถูกที่", "Geri kalanımız için iki zindan ve doğru oturan pelerinler ve kalkanlar", "Dos mazmorras para el resto de nosotros, y capas y escudos que encajan", "Duas masmorras para o resto de nós, e capas e escudos que encaixam", "Два подземелья для всех остальных и плащи со щитами, что сидят как надо", "Два підземелля для всіх інших і плащі зі щитами, що сидять як слід"],
  "The Root Cellars, under a cellar door in the grass past the Hollow Farms mill: a dungeon for new heroes (combat 3 to 15). Rats, bats, grumblins and spiders among the barrels and hay, coffers, and the Rat King at the end: rats knotted together into one furious thing, the first boss a hero meets. Nothing locked.": ["Hollow Farms の水車小屋の先、草むらの地下室の扉の下にある Root Cellars：新米の英雄向けのダンジョン（戦闘3〜15）。樽や干し草の間にネズミ、コウモリ、グランブリン、蜘蛛、宝箱、そして最奥には Rat King：ネズミが絡み合ってひとつになった怒れるもので、英雄が最初に出会うボスです。鍵のかかった扉はありません。", "Hollow Farms 방앗간 너머 풀밭의 지하실 문 아래 Root Cellars: 새 영웅을 위한 던전(전투 3~15). 통과 건초 사이의 쥐, 박쥐, 그럼블린, 거미, 보물상자, 그리고 끝에는 Rat King: 쥐들이 엉켜 하나가 된 성난 것으로, 영웅이 처음 만나는 보스입니다. 잠긴 곳은 없습니다.", "Hollow Farms 磨坊过去的草丛里有一扇地窖门，门下就是 Root Cellars：一座给新英雄的地下城（战斗 3 到 15）。木桶和干草间有老鼠、蝙蝠、嘟囔怪和蜘蛛，还有宝箱，尽头是 Rat King：一群老鼠缠结成一个暴怒的东西，是英雄遇到的第一个首领。没有上锁的地方。", "Hollow Farms 磨坊過去的草叢裡有一扇地窖門，門下就是 Root Cellars：一座給新英雄的地下城（戰鬥 3 到 15）。木桶和乾草間有老鼠、蝙蝠、嘟囔怪和蜘蛛，還有寶箱，盡頭是 Rat King：一群老鼠纏結成一個暴怒的東西，是英雄遇到的第一個首領。沒有上鎖的地方。", "Root Cellars, dưới một cửa hầm trong bãi cỏ qua cối xay Hollow Farms: hầm ngục cho anh hùng mới (chiến đấu 3 đến 15). Chuột, dơi, grumblin và nhện giữa thùng gỗ và rơm, rương báu, và Rat King ở cuối: lũ chuột quấn vào nhau thành một thứ giận dữ, con trùm đầu tiên một anh hùng gặp. Không có gì bị khóa.", "Root Cellars, di bawah pintu ruang bawah tanah di rerumputan lewat kincir Hollow Farms: ruang bawah tanah untuk pahlawan baru (tempur 3 hingga 15). Tikus, kelelawar, grumblin, dan laba-laba di antara tong dan jerami, peti, dan Rat King di ujungnya: tikus yang terjalin menjadi satu makhluk murka, bos pertama yang ditemui pahlawan. Tak ada yang terkunci.", "Root Cellars ใต้ประตูห้องใต้ดินในพงหญ้าเลยโรงโม่ Hollow Farms: ดันเจี้ยนสำหรับฮีโร่มือใหม่ (ต่อสู้ 3 ถึง 15) หนู ค้างคาว กรัมบลิน และแมงมุมท่ามกลางถังและฟาง หีบสมบัติ และ Rat King ที่ปลายทาง: หนูที่พันกันเป็นสิ่งเดียวที่โกรธจัด บอสตัวแรกที่ฮีโร่จะพบ ไม่มีอะไรล็อก", "Hollow Farms değirmeninin ötesindeki çimenlerde bir mahzen kapısının altında Root Cellars: yeni kahramanlar için bir zindan (savaş 3 ile 15). Fıçılar ve samanlar arasında sıçanlar, yarasalar, grumblinler ve örümcekler, sandıklar ve sonunda Rat King: tek bir öfkeli şeye düğümlenmiş sıçanlar, bir kahramanın karşılaştığı ilk patron. Hiçbir şey kilitli değil.", "Las Root Cellars, bajo una trampilla de sótano en la hierba pasado el molino de Hollow Farms: una mazmorra para héroes novatos (combate de 3 a 15). Ratas, murciélagos, grumblins y arañas entre barriles y heno, cofres, y el Rat King al final: ratas anudadas en una sola cosa furiosa, el primer jefe que conoce un héroe. Nada cerrado con llave.", "As Root Cellars, sob uma porta de porão na grama depois do moinho de Hollow Farms: uma masmorra para heróis novatos (combate 3 a 15). Ratos, morcegos, grumblins e aranhas entre barris e feno, baús, e o Rat King no fim: ratos enroscados numa só coisa furiosa, o primeiro chefe que um herói encontra. Nada trancado.", "Root Cellars — под дверью погреба в траве за мельницей Hollow Farms: подземелье для новых героев (бой 3–15). Крысы, летучие мыши, грамблины и пауки среди бочек и сена, сундуки, а в конце Rat King — крысы, сплетённые в одно яростное существо, первый босс, которого встречает герой. Ничего не заперто.", "Root Cellars — під дверима льоху в траві за млином Hollow Farms: підземелля для нових героїв (бій 3–15). Щури, кажани, грамбліни й павуки серед бочок і сіна, скрині, а наприкінці Rat King — щури, сплетені в одну люту істоту, перший бос, якого зустрічає герой. Нічого не замкнено."],
  "The Mossy Undercroft, down a stair in the Mossy Ruins: the vaults under the ruins, for the middle levels (25 to 45). Bandits, the dead, thornbacks and grave moths among the moss and rubble, coffers, and the Moss Warden behind a door that takes a moss key (dropped down there, found in the coffers), mending itself with the damp. It drops the Mossguard shield.": ["Mossy Ruins の階段を下りた先の Mossy Undercroft：廃墟の下の地下室で、中級者向け（25〜45）。苔と瓦礫の間に盗賊、死者、棘背、墓蛾、宝箱、そして苔の鍵（ここで落ちるか宝箱で見つかる）が必要な扉の奥に、湿気で自分を癒す Moss Warden。苔守りの盾を落とします。", "Mossy Ruins의 계단을 내려간 Mossy Undercroft: 폐허 아래 지하실로, 중간 레벨용(25~45). 이끼와 잔해 사이의 도적, 망자, 가시등, 무덤 나방, 보물상자, 그리고 이끼 열쇠(거기서 떨어지거나 보물상자에서 나옴)가 필요한 문 뒤에서 습기로 스스로를 치유하는 Moss Warden. 이끼수호 방패를 떨어뜨립니다.", "沿 Mossy Ruins 的阶梯下去就是 Mossy Undercroft：废墟下的地窖，适合中等级（25 到 45）。苔藓和碎石间有强盗、亡者、棘背兽和墓蛾，还有宝箱，以及一扇需要苔藓钥匙（下面掉落或宝箱里找到）的门后，靠湿气自愈的 Moss Warden。它会掉落苔卫盾。", "沿 Mossy Ruins 的階梯下去就是 Mossy Undercroft：廢墟下的地窖，適合中等級（25 到 45）。苔蘚和碎石間有強盜、亡者、棘背獸和墓蛾，還有寶箱，以及一扇需要苔蘚鑰匙（下面掉落或寶箱裡找到）的門後，靠濕氣自癒的 Moss Warden。牠會掉落苔衛盾。", "Mossy Undercroft, xuống một cầu thang trong Mossy Ruins: những hầm dưới phế tích, cho cấp trung (25 đến 45). Kẻ cướp, người chết, lưng gai và bướm đêm mộ giữa rêu và gạch vụn, rương báu, và Moss Warden sau một cánh cửa cần chìa khóa rêu (rơi ra dưới đó, tìm thấy trong rương), tự hồi phục nhờ hơi ẩm. Nó rơi Khiên Hộ Rêu.", "Mossy Undercroft, menuruni tangga di Mossy Ruins: ruang-ruang di bawah reruntuhan, untuk level menengah (25 hingga 45). Bandit, orang mati, punggung duri, dan ngengat kubur di antara lumut dan puing, peti, dan Moss Warden di balik pintu yang butuh kunci lumut (dijatuhkan di bawah sana, ditemukan di peti), memulihkan diri dengan kelembapan. Ia menjatuhkan Perisai Penjaga Lumut.", "Mossy Undercroft ลงบันไดใน Mossy Ruins: ห้องใต้ซากปรักหักพัง สำหรับเลเวลกลาง (25 ถึง 45) โจร คนตาย หลังหนาม และผีเสื้อกลางคืนหลุมศพท่ามกลางมอสและเศษหิน หีบสมบัติ และ Moss Warden หลังประตูที่ต้องใช้กุญแจมอส (ดรอปข้างล่างนั้นหรือเจอในหีบ) ซึ่งฟื้นตัวด้วยความชื้น มันดรอปโล่ผู้พิทักษ์มอส", "Mossy Ruins'teki bir merdivenden aşağı Mossy Undercroft: harabelerin altındaki mahzenler, orta seviyeler için (25 ile 45). Yosun ve moloz arasında haydutlar, ölüler, diken sırtlılar ve mezar güveleri, sandıklar ve bir yosun anahtarı isteyen bir kapının ardında (orada düşer, sandıklarda bulunur) nemle kendini onaran Moss Warden. Yosun muhafız kalkanı düşürür.", "La Mossy Undercroft, bajando una escalera en las Mossy Ruins: las criptas bajo las ruinas, para niveles medios (de 25 a 45). Bandidos, muertos, lomoespinos y polillas de tumba entre el musgo y los escombros, cofres, y el Moss Warden tras una puerta que pide una llave de musgo (cae allí abajo o aparece en los cofres), que se repara con la humedad. Suelta el Escudo guardamusgo.", "A Mossy Undercroft, descendo uma escada nas Mossy Ruins: as criptas sob as ruínas, para os níveis médios (25 a 45). Bandidos, mortos, dorso-espinhos e mariposas de túmulo entre o musgo e o entulho, baús, e o Moss Warden atrás de uma porta que pede uma chave de musgo (cai lá embaixo, achada nos baús), se curando com a umidade. Ele solta o Escudo guarda-musgo.", "Mossy Undercroft — вниз по лестнице в Mossy Ruins: подвалы под руинами для средних уровней (25–45). Разбойники, мертвецы, шипоспины и могильные мотыльки среди мха и обломков, сундуки и Moss Warden за дверью, для которой нужен моховой ключ (выпадает внизу, находится в сундуках); он чинит себя сыростью. С него падает щит мохового стража.", "Mossy Undercroft — униз сходами в Mossy Ruins: підвали під руїнами для середніх рівнів (25–45). Розбійники, мерці, шипоспини й могильні метелики серед моху й уламків, скрині й Moss Warden за дверима, для яких потрібен моховий ключ (випадає внизу, знаходиться в скринях); він лагодить себе вогкістю. З нього падає щит мохового стража."],
  "Statues of what waits below stand at both new mouths, and both dungeons have a track of their own.": ["新しい2つの入口には、下で待つものの像が立ち、どちらのダンジョンにも専用の曲があります。", "두 새 입구엔 아래에서 기다리는 것의 석상이 서 있고, 두 던전 모두 전용 곡이 있습니다.", "两个新入口都立着下面所等之物的雕像，两座地下城都有自己的曲子。", "兩個新入口都立著下面所等之物的雕像，兩座地下城都有自己的曲子。", "Tượng của thứ chờ bên dưới đứng ở cả hai lối vào mới, và cả hai hầm ngục đều có bản nhạc riêng.", "Patung apa yang menunggu di bawah berdiri di kedua mulut baru, dan kedua ruang bawah tanah punya lagu sendiri.", "รูปปั้นของสิ่งที่รออยู่ข้างล่างตั้งอยู่ที่ปากทางใหม่ทั้งสอง และดันเจี้ยนทั้งสองมีเพลงของตัวเอง", "İki yeni girişte de aşağıda bekleyenin heykelleri duruyor ve iki zindanın da kendi parçası var.", "Estatuas de lo que espera abajo se alzan en ambas bocas nuevas, y las dos mazmorras tienen su propia pista.", "Estátuas do que espera lá embaixo ficam nas duas bocas novas, e as duas masmorras têm faixa própria.", "У обоих новых входов стоят статуи того, что ждёт внизу, а у каждого из двух подземелий свой трек.", "Біля обох нових входів стоять статуї того, що чекає внизу, а в кожного з двох підземель свій трек."],
  "Long and four-legged Friends: the side-view cape lies over the near flank now, along the back and down past the legs, in front of the body. From behind with no cape on, a shield (the aegis included) hangs behind you on the off arm: you see your Friend's head and back, and the shield's edge past them.": ["長いフレンドや四本足のフレンド：横から見たマントは手前の脇腹の上、背中に沿って脚の下まで体の手前にかかるようになりました。マントなしで後ろから見ると、盾（イージスも）は反対の腕で背中側に掛かり、フレンドの頭と背中、その向こうに盾の縁が見えます。", "길고 네발인 프렌드: 옆에서 본 망토가 이제 가까운 옆구리 위로, 등을 따라 다리 아래까지 몸 앞에 놓입니다. 망토 없이 뒤에서 보면 방패(아이기스 포함)가 반대 팔에 걸려 등 뒤에 있어, 프렌드의 머리와 등, 그 너머로 방패 가장자리가 보입니다.", "身形长和四足的伙伴：侧视时披风现在搭在靠近的一侧身上，顺着背部垂到腿下，在身体前面。不穿披风从背后看时，盾牌（包括神盾）挂在另一只手臂上、位于你身后：你能看到伙伴的头和背，以及其后露出的盾边。", "身形長和四足的夥伴：側視時披風現在搭在靠近的一側身上，順著背部垂到腿下，在身體前面。不穿披風從背後看時，盾牌（包括神盾）掛在另一隻手臂上、位於你身後：你能看到夥伴的頭和背，以及其後露出的盾邊。", "Bạn dài và bốn chân: áo choàng nhìn từ bên giờ phủ lên sườn gần, dọc lưng và xuống qua chân, ở phía trước thân. Nhìn từ sau khi không mặc áo choàng, khiên (cả khiên thánh) treo sau bạn trên tay kia: bạn thấy đầu và lưng của Bạn, và mép khiên lộ ra phía sau.", "Sahabat panjang dan berkaki empat: jubah tampak samping kini berada di atas sisi dekat, sepanjang punggung dan turun melewati kaki, di depan tubuh. Dari belakang tanpa jubah, perisai (termasuk aegis) tergantung di belakangmu di lengan lain: kau melihat kepala dan punggung Sahabatmu, dan tepi perisai di baliknya.", "เพื่อนตัวยาวและสี่ขา: ผ้าคลุมเมื่อมองด้านข้างตอนนี้พาดอยู่บนสีข้างด้านใกล้ ตามแนวหลังและลงผ่านขา อยู่ด้านหน้าลำตัว มองจากด้านหลังโดยไม่ใส่ผ้าคลุม โล่ (รวมอีจิส) ห้อยอยู่ข้างหลังคุณบนแขนอีกข้าง: คุณเห็นหัวและหลังของเพื่อน และขอบโล่ที่โผล่ออกมา", "Uzun ve dört ayaklı Dostlar: yandan görünen pelerin artık yakın böğrün üstünde, sırt boyunca ve bacakların aşağısına kadar, bedenin önünde duruyor. Pelerinsiz arkadan bakınca kalkan (egis dahil) öbür kolunda arkanda asılı: Dostunun başını ve sırtını, ötesinde de kalkanın kenarını görürsün.", "Amigos alargados y de cuatro patas: la capa vista de lado cae ahora sobre el costado cercano, a lo largo del lomo y bajando más allá de las patas, delante del cuerpo. Por detrás y sin capa, el escudo (la égida incluida) cuelga a tu espalda en el otro brazo: ves la cabeza y la espalda de tu Amigo y el borde del escudo asomando.", "Amigos compridos e de quatro patas: a capa vista de lado agora fica sobre o flanco próximo, ao longo das costas e descendo além das pernas, na frente do corpo. Por trás e sem capa, o escudo (a égide incluída) fica pendurado atrás de você no outro braço: você vê a cabeça e as costas do seu Amigo e a borda do escudo aparecendo.", "Длинные и четвероногие Друзья: плащ при виде сбоку теперь лежит на ближнем боку, вдоль спины и ниже ног, перед телом. Если смотреть сзади без плаща, щит (и эгида) висит позади на другой руке: видны голова и спина Друга, а за ними — край щита.", "Довгі й чотириногі Друзі: плащ при погляді збоку тепер лежить на ближньому боці, уздовж спини й нижче ніг, перед тілом. Якщо дивитися ззаду без плаща, щит (і егіда) висить позаду на іншій руці: видно голову й спину Друга, а за ними — край щита."],
};
